mapper.select:
/* isry.csemd.sysmng.srvymng.mapper.SrvyMngMapper - selectSrvyChart */ /* Lee SeoungJae[설문차트 조회] */ --설문영역명 가져오기위한 WITH문 WITH TEMP AS( SELECT TRIM(QUSTNB_GRDNG_RELM_ESNTAL_NM) AS QUSTNB_GRDNG_RELM_ESNTAL_NM , QUSTNB_GRDNG_RELM_MNG_NO FROM SBB030 WHERE QUSTNB_TMPT_MNG_NO IN ( --설문지템플릿관리번호 (SELECT ADDTNG_MNG_VALUE1 --추가관리값1 FROM SAC100 /*공통코드 테이블*/ WHERE CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' --공통코드아이디 = 설문지종류구분코드 AND CMMNS_CD_VALUE= #{QUSTNB_KND_SE_CD}) --공통코드 값 ) ORDER BY QUSTNB_GRDNG_RELM_MNG_NO )
--ROWNUM 가져오기 위함 SELECT QUSTNB_GRDNG_RELM_ESNTAL_NM,BEFFAT_SCORE_AVG, AFTFCT_SCORE_AVG, ROWNUM AS ROW_NUM FROM (
--평균 SELECT '평균' AS QUSTNB_GRDNG_RELM_ESNTAL_NM --설문지채점영역고유명(평균) , ROUND(AVG( CASE WHEN D.SRVY_ERA_SE_CD = '01' THEN A.GRDNG_SCORE END),2) AS BEFFAT_SCORE_AVG --사전점수평균 , ROUND(AVG( CASE WHEN D.SRVY_ERA_SE_CD = '02' THEN A.GRDNG_SCORE END),2) AS AFTFCT_SCORE_AVG --사후점수평균 FROM SBB510 A /*채점결과 테이블*/ INNER JOIN SBB130 B /*채점영역설정 테이블*/ ON A.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO --설문지템플릿관리번호 AND A.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO --설문지채점영역고유명 INNER JOIN SBB500 C /*설문응답 테이블*/ ON C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO --설문지템플릿관리번호 AND C.SRVY_RSPNS_MNG_NO = A.SRVY_RSPNS_MNG_NO --설문지응답관리번호
INNER JOIN ( SELECT SRVY_ERA_SE_CD , QUSTNB_TMPT_MNG_NO , QUSTNB_MNG_NO , UNT_TASKWK_SE_CD , INST_NO , SRVC_EXCN_BIZ_NO , SRVY_RSPDNT_NM_ENCPT , MNG_SN , TRPR_INFO_NO , ROW_NUMBER() OVER(PARTITION BY INST_NO, TRPR_INFO_NO, QUSTNB_TMPT_MNG_NO, SRVY_ERA_SE_CD, TRPR_REL_SE_CD ORDER BY REG_YMD DESC, MNG_SN DESC) AS RN FROM SBB600
WHERE SRVY_RSPDNT_NM_ENCPT = ENC_B64(#{SRVY_RSPDNT_NM}) --설문응답자명암호화
)D /*설문발송이력 테이블*/ ON D.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO --설문지템플릿관리번호 AND D.QUSTNB_MNG_NO = C.QUSTNB_MNG_NO --설문지관리번호 WHERE A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} --단위업무구분코드 AND D.INST_NO LIKE #{INST_NO} || '%' --기관구분코드 AND D.SRVC_EXCN_BIZ_NO LIKE #{SRVC_EXCN_BIZ_NO} || '%' --서비스실행사업번호 AND D.SRVY_ERA_SE_CD LIKE #{SRVY_ERA_SE_CD} || '%' --설문시기구분코드 AND A.QUSTNB_TMPT_MNG_NO IN ( --설문지템플릿관리번호 (SELECT ADDTNG_MNG_VALUE1 --추가관리값1 FROM SAC100 /*공통코드 테이블*/ WHERE CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' --공통코드아이디 = 설문지종류구분코드 AND CMMNS_CD_VALUE= #{QUSTNB_KND_SE_CD}) --공통코드 값 , (SELECT ADDTNG_MNG_VALUE2 --추가관리값2 FROM SAC100 /*공통코드 테이블*/ WHERE CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' --공통코드아이디 = 설문지종류구분코드 AND CMMNS_CD_VALUE= #{QUSTNB_KND_SE_CD}) --공통코드 값 ) AND TO_CHAR(C.RSPNS_DT,'YYYYMMDD') BETWEEN #{BGNG_YMD} AND #{END_YMD} --응답일시 AND D.RN = 1
UNION ALL
--통계 데이터 SELECT QUSTNB_GRDNG_RELM_ESNTAL_NM, BEFFAT_SCORE_AVG, AFTFCT_SCORE_AVG FROM( SELECT B.QUSTNB_GRDNG_RELM_ESNTAL_NM, A.BEFFAT_SCORE_AVG, A.AFTFCT_SCORE_AVG, B.QUSTNB_GRDNG_RELM_MNG_NO FROM( SELECT TRIM(B.QUSTNB_GRDNG_RELM_ESNTAL_NM) AS QUSTNB_GRDNG_RELM_ESNTAL_NM --설문지채점영역고유명 , ROUND(AVG( CASE WHEN D.SRVY_ERA_SE_CD = '01' THEN A.GRDNG_SCORE END),2) AS BEFFAT_SCORE_AVG --사전점수평균 , ROUND(AVG( CASE WHEN D.SRVY_ERA_SE_CD = '02' THEN A.GRDNG_SCORE END),2) AS AFTFCT_SCORE_AVG --사후점수평균 FROM SBB510 A /*채점결과 테이블*/ INNER JOIN SBB130 B /*채점영역설정 테이블*/ ON A.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO --설문지템플릿관리번호 AND A.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO --설문지채점영역고유명 INNER JOIN SBB500 C /*설문응답 테이블*/ ON C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO --설문지템플릿관리번호 AND C.SRVY_RSPNS_MNG_NO = A.SRVY_RSPNS_MNG_NO --설문지응답관리번호 INNER JOIN ( SELECT SRVY_ERA_SE_CD , QUSTNB_TMPT_MNG_NO , QUSTNB_MNG_NO , UNT_TASKWK_SE_CD , INST_NO , SRVC_EXCN_BIZ_NO , SRVY_RSPDNT_NM_ENCPT , MNG_SN , TRPR_INFO_NO , ROW_NUMBER() OVER(PARTITION BY INST_NO, TRPR_INFO_NO, QUSTNB_TMPT_MNG_NO, SRVY_ERA_SE_CD, TRPR_REL_SE_CD ORDER BY REG_YMD DESC, MNG_SN DESC) AS RN FROM SBB600
WHERE SRVY_RSPDNT_NM_ENCPT = ENC_B64(#{SRVY_RSPDNT_NM}) --설문응답자명암호화
)D /*설문발송이력 테이블*/ ON D.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO --설문지템플릿관리번호 AND D.QUSTNB_MNG_NO = C.QUSTNB_MNG_NO --설문지관리번호 WHERE A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} --단위업무구분코드 AND D.INST_NO LIKE #{INST_NO} || '%' --기관구분코드 AND D.SRVC_EXCN_BIZ_NO LIKE #{SRVC_EXCN_BIZ_NO} || '%' --서비스실행사업번호 AND D.SRVY_ERA_SE_CD LIKE #{SRVY_ERA_SE_CD} || '%' --설문시기구분코드 AND A.QUSTNB_TMPT_MNG_NO IN ( --설문지템플릿관리번호 (SELECT ADDTNG_MNG_VALUE1 --추가관리값1 FROM SAC100 /*공통코드 테이블*/ WHERE CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' --공통코드아이디 = 설문지종류구분코드 AND CMMNS_CD_VALUE= #{QUSTNB_KND_SE_CD} --공통코드 값 ) , (SELECT ADDTNG_MNG_VALUE2 --추가관리값2 FROM SAC100 /*공통코드 테이블*/ WHERE CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' --공통코드아이디 = 설문지종류구분코드 AND CMMNS_CD_VALUE= #{QUSTNB_KND_SE_CD}) --공통코드 값 ) AND TO_CHAR(C.RSPNS_DT,'YYYYMMDD') BETWEEN #{BGNG_YMD} AND #{END_YMD} --응답일시 AND D.RN = 1 GROUP BY B.QUSTNB_GRDNG_RELM_ESNTAL_NM ) A INNER JOIN TEMP B ON A.QUSTNB_GRDNG_RELM_ESNTAL_NM = B.QUSTNB_GRDNG_RELM_ESNTAL_NM ORDER BY QUSTNB_GRDNG_RELM_MNG_NO ) )

/* isry.csemd.sysmng.srvymng.mapper.SrvyMngMapper - selectQustnbKndSeCd */
/* Lee SeoungJae[설문내용 분석내용 설문지종류구분코드 조회] */
SELECT CMMNS_CD_VALUE AS QUSTNB_KND_SE_CD
FROM SAC100
WHERE CMMNS_CD_ID = 'QUSTNB_KND_SE_CD'
AND (
    SELECT QUSTNB_TMPT_MNG_NO
    FROM SBB600
    WHERE INST_NO = #{INST_NO}
    AND REG_YMD = #{REG_YMD}
    AND MNG_SN = #{MNG_SN}
    ) IN (ADDTNG_MNG_VALUE1, ADDTNG_MNG_VALUE2)

AND ROWNUM <= 1

/* isry.csemd.sysmng.srvymng.mapper.SrvyMngMapper - selectSrvyRecodeList */ /* Park SeongWon[설문이력목록 조회] */ SELECT * FROM (SELECT T1.INST_NO AS INST_NO /* 기관번호 */ , T1.SRVC_EXCN_BIZ_NO AS SRVC_EXCN_BIZ_NO /* 서비스실행사업번호 */ , T1.TRPR_INFO_NO AS TRPR_INFO_NO /* 대상자정보번호 */ , T1.TRPR_REL_SE_CD AS TRPR_REL_SE_CD /* 대상자관계구분코드 */ , T1.SRVY_ERA_SE_CD AS SRVY_ERA_SE_CD /* 설문시기구분코드 */ , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'YES_OR_NO' AND CMMNS_CD_VALUE = T1.NO_INPT_SNDNG_YN) AS NO_INPT_SNDNG_YN /* 번호입력발송여부 */ , DEC_B64(T1.SRVY_RSPDNT_NM_ENCPT) AS SRVY_RSPDNT_NM_ENCPT /* 설문응답자명암호화 */ , DEC_B64(T1.SRVY_RSPNS_RCPTN_MBL_TELNO_ENCPT) AS SRVY_RSPNS_RCPTN_MBL_TELNO_ENCPT /* 설문응답수신휴대전화번호 */ , T1.CHRCTR_CN AS CHRCTR_CN /* 문자내용 */ , T1.ALTMNT_GROUP_SCLAS_SE_CD AS ALTMNT_GROUP_SCLAS_SE_CD /* 배정그룹구분코드 */ , T1.SNDNG_DT AS SNDNG_DT /* 발송일시 */ , T1.SRVY_RCPTN_MTHD_SE_CD AS SRVY_RCPTN_MTHD_SE_CD /* 설문수신방법구분코드 */ , T1.REG_YMD AS REG_YMD /* 등록일자 */ , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'YES_OR_NO' AND CMMNS_CD_VALUE = T1.RSVT_SNDNG_YN) AS RSVT_SNDNG_YN /* 예약발송여부 */ , T1.MNG_SN AS MNG_SN /* 관리일련번호 */ , T1.QUSTNB_MNG_NO AS QUSTNB_MNG_NO /* 설문지관리번호 */ , DEC_B64(T2.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT /* 대상자명 암호화 */ , T2.TRPR_BRTH_YMD AS TRPR_BRTH_YMD /* 대상자 출생일자 */ , TRUNC(MONTHS_BETWEEN(SYSDATE, T2.TRPR_BRTH_YMD) /12) AS AGE /* 만 나이 */ , ( SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID LIKE 'SXDC_SE_CD' AND CMMNS_CD_VALUE = T2.SXDC_SE_CD ) AS SXDC_SE_CD /* 성별구분코드 */ , ( SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID LIKE 'ACBG_SE_CD' AND CMMNS_CD_VALUE = T2.ACBG_SE_CD ) AS ACBG_SE_CD /* 학력구분코드 */ , CASE T1.TRPR_REL_SE_CD WHEN '11' THEN T2.TRPR_BRTH_YMD WHEN '12' THEN T2.PRTCR_BRTH_YMD END AS SRVY_RSPDNT_BRTH_YMD /* 설문응답자 생년월일 */ , TRUNC(MONTHS_BETWEEN(SYSDATE, CASE T1.TRPR_REL_SE_CD WHEN '11' THEN T2.TRPR_BRTH_YMD WHEN '12' THEN T2.PRTCR_BRTH_YMD END)/12,0) AS SRVY_RSPDNT_AGE /* 설문응답자 만나이 */ , ( SELECT SUM(GRDNG_SCORE) FROM SBB510 WHERE QUSTNB_MNG_NO = T6.QUSTNB_MNG_NO AND QUSTNB_TMPT_MNG_NO = T6.QUSTNB_TMPT_MNG_NO AND SRVY_RSPNS_MNG_NO = T6.SRVY_RSPNS_MNG_NO ) AS GRDNG_SCORE /* 채점점수 */ , T6.RSPNS_DT AS RSPNS_DT /* 설문응답일시 */ , T7.QUSTNB_NM AS QUSTNB_NM /* 설문지종류 */ , T7.QUSTNB_TMPT_MNG_NO AS QUSTNB_TMPT_MNG_NO /* 설문지 관리번호 */ , T7.SRVY_PRGRS_STTS_SE_CD AS SRVY_PRGRS_STTS_SE_CD /* 설문진행상태구분코드 */ , T9.BIZ_YR AS BIZ_YR /* 사업연도 */ , ROW_NUMBER() OVER(PARTITION BY T1.INST_NO, T1.TRPR_INFO_NO, T1.QUSTNB_TMPT_MNG_NO, T1.SRVY_ERA_SE_CD, T1.TRPR_REL_SE_CD ORDER BY T1.REG_YMD DESC, T1.MNG_SN DESC) AS RN
FROM SBB600 T1 LEFT JOIN SAC100 T ON T.CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' AND (T.ADDTNG_MNG_VALUE1 = T1.QUSTNB_TMPT_MNG_NO OR T.ADDTNG_MNG_VALUE2 = T1.QUSTNB_TMPT_MNG_NO) INNER JOIN SEA200 T2 ON T2.TRPR_INFO_NO = T1.TRPR_INFO_NO LEFT JOIN (SELECT A.* ,ROW_NUMBER() OVER(PARTITION BY A.TRPR_INFO_NO ORDER BY B.ADDTNG_MNG_VALUE1 DESC, A.MNG_SN DESC) AS RN FROM SEA230 A LEFT JOIN SAC100 B ON CMMNS_CD_ID = 'ACBG_SE_CD' AND CMMNS_CD_VALUE = A.ACBG_SE_CD WHERE A.DEL_YN != 'Y' ) T3 ON T3.RN = 1 AND T3.TRPR_INFO_NO = T2.TRPR_INFO_NO LEFT JOIN AFA100 T4 ON T4.TRPR_INFO_NO = T1.TRPR_INFO_NO AND T4.APLY_RCPT_SN = T1.APLY_RCPT_SN LEFT JOIN SBB500 T6 ON T6.QUSTNB_MNG_NO = T1.QUSTNB_MNG_NO AND T6.QUSTNB_TMPT_MNG_NO = T1.QUSTNB_TMPT_MNG_NO AND T6.SRVY_RSPNS_MNG_NO = (SELECT MAX(SRVY_RSPNS_MNG_NO) FROM SBB500 WHERE QUSTNB_MNG_NO = T1.QUSTNB_MNG_NO) LEFT JOIN SBB100 T7 ON T7.QUSTNB_TMPT_MNG_NO = T1.QUSTNB_TMPT_MNG_NO AND T7.QUSTNB_MNG_NO = T1.QUSTNB_MNG_NO LEFT JOIN SDA420 T8 ON T8.SRVC_EXCN_BIZ_NO = T1.SRVC_EXCN_BIZ_NO LEFT JOIN SDA400 T9 ON T9.SRVC_BIZ_NO = T8.SRVC_BIZ_NO WHERE 1=1 AND T1.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND T1.REG_YMD BETWEEN #{START_DATE} AND #{END_DATE}
/* 서비스실행사업번호 */ AND T1.SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO}
/* 설문지종류구분코드 */ AND T.CMMNS_CD_VALUE = #{QUSTNB_KND_SE_CD}
/* 사업연도 */ AND T9.BIZ_YR = #{BIZ_YR}
/* 기관번호 */ AND T1.INST_NO = #{INST_NO}
/* 배정그룹구분코드(생활동) */ AND T1.ALTMNT_GROUP_SCLAS_SE_CD = #{ALTMNT_GROUP_SCLAS_SE_CD}
/* 설문진행상태 */ AND T7.SRVY_PRGRS_STTS_SE_CD = #{SRVY_PRGRS_STTS_SE_CD}
/* 설문시기 */ AND T1.SRVY_ERA_SE_CD = #{SRVY_ERA_SE_CD}
/* 대상자와의관계 */ AND T1.TRPR_REL_SE_CD = #{TRPR_REL_SE_CD}
/* 설문응답자 */ AND T1.SRVY_RSPDNT_NM_ENCPT = ENC_B64(#{SRVY_RSPDNT_NM})
/* 대상자 */ AND T2.TRPR_NM_ENCPT = ENC_B64(#{TRPR_NM})
/* 설문수신방법구분코드 */ AND T1.SRVY_RCPTN_MTHD_SE_CD = #{SRVY_RCPTN_MTHD_SE_CD}
/* 설문응답자수신번호 */ AND T1.SRVY_RSPNS_RCPTN_MBL_TELNO_ENCPT = ENC_B64(#{SRVY_RSPNS_RCPTN_MBL_TELNO})
) T1 WHERE T1.RN = 1 ORDER BY T1.REG_YMD DESC, T1.MNG_SN DESC

/* selectSrvySndngList (설문발송 대상자 선택 리스트 조회) - Lee Hye Sun */
SELECT X.INST_NO --기관번호 , X.INST_NM --기관명 , X.SRVC_EXCN_BIZ_NM --서비스실행사업명 , X.SRVC_EXCN_BIZ_NO --서비스실행사업번호 , X.ALTMNT_GROUP_SCLAS_SE_CD --배정그룹소분류구분코드 , X.DORMIT_NM --배정그룹명 , X.TRPR_REL_CD --대상자관계구분코드 , X.TRPR_REL --대상자관계명 , DEC_B64(X.RSPDNT) AS RSPDNT --응답자 , DEC_B64(X.RSPDNT_RCPTN) AS RSPDNT_RCPTN --응답자수신번호 , CASE WHEN X.RSPDNT_BRDT IS NULL THEN NULL ELSE X.RSPDNT_BRDT || '(만' || TRUNC(MONTHS_BETWEEN(TRUNC(SYSDATE), TO_DATE(X.RSPDNT_BRDT, 'YYYYMMDD')) / 12) || '세)' END AS RSPDNT_BRDT --응답자생년월일 , X.TRPR_INFO_NO --대상자정보번호 , X.APLY_RCPT_SN --신청접수일련번호 , DEC_B64(X.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT --대상자 , CASE WHEN X.TRPR_BRTH_YMD IS NULL THEN NULL ELSE X.TRPR_BRTH_YMD || '(만' || TRUNC(MONTHS_BETWEEN(TRUNC(SYSDATE), TO_DATE(X.TRPR_BRTH_YMD, 'YYYYMMDD')) / 12) || '세)' END AS TRPR_BRTH_YMD --대상자생년월일(만나이) , X.SXDC_SE_CD --대상자성별코드 , X.SXDC_SE_CD_NM --대상자성별 , X.ACBG_SE_CD --대상자학력 , X.BIZ_YR , X.CASE_MNG_NO , X.CASE_MNG_ODRNO , RSPDNT_RCPTN AS NO_MASK_RSPDNT_RCPTN FROM ( /*대상자*/ SELECT D.INST_NO --기관번호 , D.INST_NM --기관명 , B.SRVC_EXCN_BIZ_NM --서비스실행사업명 , B.SRVC_EXCN_BIZ_NO --서비스실행사업번호 , E.ALTMNT_GROUP_SCLAS_SE_CD --배정그룹소분류구분코드 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'ALTMNT_GROUP_SCLAS_SE_CD' AND CMMNS_CD_VALUE = E.ALTMNT_GROUP_SCLAS_SE_CD ) AS DORMIT_NM --배정그룹명 , CASE WHEN F.TRPR_REL_SE_CD = '11' THEN '11' ELSE '11' END AS TRPR_REL_CD , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'TRPR_REL_SE_CD' AND CMMNS_CD_VALUE = '11' ) AS TRPR_REL --대상자관계명 , NVL(T.FLNM_ENCPT, F.TRPR_NM_ENCPT) AS RSPDNT --대상자 , NVL(T.MBL_TELNO_ENCPT, F.MBL_TELNO_ENCPT) AS RSPDNT_RCPTN --대상자수신번호 , NVL(T.BRTH_YMD, F.TRPR_BRTH_YMD) AS RSPDNT_BRDT --대상자생년월일 , F.TRPR_INFO_NO --대상자정보번호 , W.APLY_RCPT_SN --신청접수일련번호 , NVL(T.FLNM_ENCPT, F.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT --대상자 , NVL(T.BRTH_YMD, F.TRPR_BRTH_YMD) AS TRPR_BRTH_YMD --대상자생년월일(만나이) , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' AND CMMNS_CD_VALUE = NVL(T.SXDC_SE_CD, F.SXDC_SE_CD) ) AS SXDC_SE_CD_NM --대상자성별 , (SELECT CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' AND CMMNS_CD_VALUE = NVL(T.SXDC_SE_CD, F.SXDC_SE_CD) ) AS SXDC_SE_CD --대상자성별코드 , C.ACBG AS ACBG_SE_CD --대상자학력 , S.BIZ_YR --사업연도 , E.CASE_MNG_NO , E.CASE_MNG_ODRNO FROM SEB120 A /*서비스사업대상자*/ LEFT JOIN SDA420 B /*서비스실행사업*/ ON A.SRVC_EXCN_BIZ_NO = B.SRVC_EXCN_BIZ_NO LEFT JOIN SDA400 S /*서비스사업*/ ON B.SRVC_BIZ_NO = S.SRVC_BIZ_NO LEFT JOIN SAA000 D /*통합기관*/ ON D.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} LEFT JOIN SEB100 E /*사례기본*/ ON A.CASE_MNG_NO = E.CASE_MNG_NO AND A.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO LEFT JOIN SEA200 F /*대상자정보*/ ON E.TRPR_INFO_NO = F.TRPR_INFO_NO LEFT JOIN AFA100 W /*신청접수*/ ON F.TRPR_INFO_NO = W.TRPR_INFO_NO LEFT JOIN SCA300 T /*개인정보*/ ON T.INDV_IDNTFC_NO = F.INDV_IDNTFC_NO LEFT JOIN ( SELECT TRPR_INFO_NO , ACBG FROM ( SELECT Q1.* , ROW_NUMBER() OVER(PARTITION BY Q1.TRPR_INFO_NO ORDER BY Q2.SRTNG_SQNCE DESC, Q3.SRTNG_SQNCE DESC) ROW_NO , NVL(Q2.CMMNS_CD_VALUE_NM, ' ') || NVL(Q4.CMMNS_CD_VALUE_NM, ' ') || NVL(Q3.CMMNS_CD_VALUE_NM, ' ') AS ACBG --대상자학력 FROM SEA230 Q1 LEFT JOIN SAC100 Q2 /* 최종학력구분코드 */ ON Q2.CMMNS_CD_ID = 'ACBG_SE_CD' AND Q2.CMMNS_CD_VALUE = Q1.ACBG_SE_CD LEFT JOIN SAC100 Q3 /* 졸업상태 구분코드 */ ON Q3.CMMNS_CD_ID = 'GRDTN_STTS_SE_CD' AND Q3.CMMNS_CD_VALUE = Q1.GRDTN_STTS_SE_CD LEFT JOIN SAC100 Q4 /* 학년 구분코드 */ ON Q4.CMMNS_CD_ID = 'GRADE_SE_CD' AND Q4.CMMNS_CD_VALUE = Q1.GRADE_SE_CD WHERE Q1.DEL_YN = 'N' ) WHERE ROW_NO = 1 ) C ON C.TRPR_INFO_NO = F.TRPR_INFO_NO
UNION ALL
/*보호자*/ SELECT D.INST_NO --기관번호 , D.INST_NM --기관명 , B.SRVC_EXCN_BIZ_NM --서비스실행사업명 , B.SRVC_EXCN_BIZ_NO --서비스실행사업번호 , E.ALTMNT_GROUP_SCLAS_SE_CD --배정그룹소분류구분코드 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'ALTMNT_GROUP_SCLAS_SE_CD' AND CMMNS_CD_VALUE = E.ALTMNT_GROUP_SCLAS_SE_CD ) AS DORMIT_NM --배정그룹명 , CASE WHEN F.TRPR_REL_SE_CD = '12' THEN '12' ELSE '12' END AS TRPR_REL_CD , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'TRPR_REL_SE_CD' AND CMMNS_CD_VALUE = '12' ) AS TRPR_REL --대상자관계명 , F.PRTCR_NM_ENCPT AS RSPDNT --응답자 , F.PRTCR_MBL_TELNO_ENCPT AS RSPDNT_RCPTN --응답자수신번호 , F.PRTCR_BRTH_YMD AS RSPDNT_BRDT --응답자생년월일 , F.TRPR_INFO_NO --대상자정보번호 , W.APLY_RCPT_SN --신청접수일련번호 , NVL(T.FLNM_ENCPT, F.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT --대상자 , NVL(T.BRTH_YMD, F.TRPR_BRTH_YMD) AS TRPR_BRTH_YMD --대상자생년월일(만나이) , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' AND CMMNS_CD_VALUE = NVL(T.SXDC_SE_CD, F.SXDC_SE_CD) ) AS SXDC_SE_CD_NM --대상자성별 , (SELECT CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' AND CMMNS_CD_VALUE = NVL(T.SXDC_SE_CD, F.SXDC_SE_CD) ) AS SXDC_SE_CD --대상자성별코드 , C.ACBG AS ACBG_SE_CD --대상자학력 , S.BIZ_YR --사업연도 , E.CASE_MNG_NO , E.CASE_MNG_ODRNO FROM SEB120 A /*서비스사업대상자*/ LEFT JOIN SDA420 B /*서비스실행사업*/ ON A.SRVC_EXCN_BIZ_NO = B.SRVC_EXCN_BIZ_NO LEFT JOIN SDA400 S /*서비스사업*/ ON B.SRVC_BIZ_NO = S.SRVC_BIZ_NO LEFT JOIN SAA000 D /*통합기관*/ ON D.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} LEFT JOIN SEB100 E /*사례기본*/ ON A.CASE_MNG_NO = E.CASE_MNG_NO AND A.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO LEFT JOIN SEA200 F /*대상자정보*/ ON E.TRPR_INFO_NO = F.TRPR_INFO_NO LEFT JOIN AFA100 W /*신청접수*/ ON F.TRPR_INFO_NO = W.TRPR_INFO_NO LEFT JOIN SCA300 T /*개인정보*/ ON T.INDV_IDNTFC_NO = F.INDV_IDNTFC_NO LEFT JOIN ( SELECT TRPR_INFO_NO , ACBG FROM ( SELECT Q1.* , ROW_NUMBER() OVER(PARTITION BY Q1.TRPR_INFO_NO ORDER BY Q2.SRTNG_SQNCE DESC, Q3.SRTNG_SQNCE DESC) ROW_NO , NVL(Q2.CMMNS_CD_VALUE_NM, ' ') || NVL(Q4.CMMNS_CD_VALUE_NM, ' ') || NVL(Q3.CMMNS_CD_VALUE_NM, ' ') AS ACBG --대상자학력 FROM SEA230 Q1 LEFT JOIN SAC100 Q2 /* 최종학력구분코드 */ ON Q2.CMMNS_CD_ID = 'ACBG_SE_CD' AND Q2.CMMNS_CD_VALUE = Q1.ACBG_SE_CD LEFT JOIN SAC100 Q3 /* 졸업상태 구분코드 */ ON Q3.CMMNS_CD_ID = 'GRDTN_STTS_SE_CD' AND Q3.CMMNS_CD_VALUE = Q1.GRDTN_STTS_SE_CD LEFT JOIN SAC100 Q4 /* 학년 구분코드 */ ON Q4.CMMNS_CD_ID = 'GRADE_SE_CD' AND Q4.CMMNS_CD_VALUE = Q1.GRADE_SE_CD WHERE Q1.DEL_YN = 'N' ) WHERE ROW_NO = 1 ) C ON C.TRPR_INFO_NO = F.TRPR_INFO_NO
UNION ALL
/*의뢰담당자*/ SELECT D.INST_NO --기관번호 , D.INST_NM --기관명 , B.SRVC_EXCN_BIZ_NM --서비스실행사업명 , B.SRVC_EXCN_BIZ_NO --서비스실행사업번호 , E.ALTMNT_GROUP_SCLAS_SE_CD --배정그룹소분류구분코드 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'ALTMNT_GROUP_SCLAS_SE_CD' AND CMMNS_CD_VALUE = E.ALTMNT_GROUP_SCLAS_SE_CD ) AS DORMIT_NM --배정그룹명 , CASE WHEN F.TRPR_REL_SE_CD = '13' THEN '13' ELSE '13' END AS TRPR_REL_CD , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'TRPR_REL_SE_CD' AND CMMNS_CD_VALUE = '13' ) AS TRPR_REL --대상자관계명 , G.PIC_NM_ENCPT AS RSPDNT --응답자 , G.PIC_MBL_TELNO_ENCPT AS RSPDNT_RCPTN --응답자수신번호 , NULL AS RSPDNT_BRDT --응답자생년월일 , F.TRPR_INFO_NO --대상자정보번호 , G.APLY_RCPT_SN --신청접수일련번호 , NVL(T.FLNM_ENCPT, F.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT --대상자 , NVL(T.BRTH_YMD, F.TRPR_BRTH_YMD) AS TRPR_BRTH_YMD --대상자생년월일(만나이) , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' AND CMMNS_CD_VALUE = NVL(T.SXDC_SE_CD, F.SXDC_SE_CD) ) AS SXDC_SE_CD_NM --대상자성별 , (SELECT CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' AND CMMNS_CD_VALUE = NVL(T.SXDC_SE_CD, F.SXDC_SE_CD) ) AS SXDC_SE_CD --대상자성별코드 , C.ACBG AS ACBG_SE_CD --대상자학력 , S.BIZ_YR , E.CASE_MNG_NO , E.CASE_MNG_ODRNO FROM SEB120 A /*서비스사업대상자*/ LEFT JOIN SDA420 B /*서비스실행사업*/ ON A.SRVC_EXCN_BIZ_NO = B.SRVC_EXCN_BIZ_NO LEFT JOIN SDA400 S /*서비스사업*/ ON B.SRVC_BIZ_NO = S.SRVC_BIZ_NO LEFT JOIN SAA000 D /*통합기관*/ ON D.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} LEFT JOIN SEB100 E /*사례기본*/ ON A.CASE_MNG_NO = E.CASE_MNG_NO AND A.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO LEFT JOIN SEA200 F /*대상자정보*/ ON E.TRPR_INFO_NO = F.TRPR_INFO_NO LEFT JOIN AFA100 G /*신청접수*/ ON F.TRPR_INFO_NO = G.TRPR_INFO_NO LEFT JOIN SCA300 T /*개인정보*/ ON T.INDV_IDNTFC_NO = F.INDV_IDNTFC_NO LEFT JOIN ( SELECT TRPR_INFO_NO , ACBG FROM ( SELECT Q1.* , ROW_NUMBER() OVER(PARTITION BY Q1.TRPR_INFO_NO ORDER BY Q2.SRTNG_SQNCE DESC, Q3.SRTNG_SQNCE DESC) ROW_NO , NVL(Q2.CMMNS_CD_VALUE_NM, ' ') || NVL(Q4.CMMNS_CD_VALUE_NM, ' ') || NVL(Q3.CMMNS_CD_VALUE_NM, ' ') AS ACBG --대상자학력 FROM SEA230 Q1 LEFT JOIN SAC100 Q2 /* 최종학력구분코드 */ ON Q2.CMMNS_CD_ID = 'ACBG_SE_CD' AND Q2.CMMNS_CD_VALUE = Q1.ACBG_SE_CD LEFT JOIN SAC100 Q3 /* 졸업상태 구분코드 */ ON Q3.CMMNS_CD_ID = 'GRDTN_STTS_SE_CD' AND Q3.CMMNS_CD_VALUE = Q1.GRDTN_STTS_SE_CD LEFT JOIN SAC100 Q4 /* 학년 구분코드 */ ON Q4.CMMNS_CD_ID = 'GRADE_SE_CD' AND Q4.CMMNS_CD_VALUE = Q1.GRADE_SE_CD WHERE Q1.DEL_YN = 'N' ) WHERE ROW_NO = 1 ) C ON C.TRPR_INFO_NO = F.TRPR_INFO_NO
UNION ALL
/*지도자*/
SELECT D.INST_NO --기관번호 , D.INST_NM --기관명 , B.SRVC_EXCN_BIZ_NM --서비스실행사업명 , B.SRVC_EXCN_BIZ_NO --서비스실행사업번호 , E.ALTMNT_GROUP_SCLAS_SE_CD --배정그룹소분류구분코드 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'ALTMNT_GROUP_SCLAS_SE_CD' AND CMMNS_CD_VALUE = E.ALTMNT_GROUP_SCLAS_SE_CD ) AS DORMIT_NM --배정그룹명 , CASE WHEN F.TRPR_REL_SE_CD = '14' THEN '14' ELSE '14' END AS TRPR_REL_CD , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'TRPR_REL_SE_CD' AND CMMNS_CD_VALUE = '14' ) AS TRPR_REL --대상자관계명 , H.FLNM_ENCPT AS RSPDNT --응답자 , H.MBL_TELNO_ENCPT AS RSPDNT_RCPTN --응답자수신번호 , H.BRTH_YMD AS RSPDNT_BRDT --응답자생년월일 , F.TRPR_INFO_NO --대상자정보번호 , W.APLY_RCPT_SN --신청접수일련번호 , NVL(T.FLNM_ENCPT, F.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT --대상자 , NVL(T.BRTH_YMD, F.TRPR_BRTH_YMD) AS TRPR_BRTH_YMD --대상자생년월일(만나이) , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' AND CMMNS_CD_VALUE = NVL(T.SXDC_SE_CD, F.SXDC_SE_CD) ) AS SXDC_SE_CD_NM --대상자성별 , (SELECT CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' AND CMMNS_CD_VALUE = NVL(T.SXDC_SE_CD, F.SXDC_SE_CD) ) AS SXDC_SE_CD --대상자성별코드 , C.ACBG AS ACBG_SE_CD --대상자학력 , S.BIZ_YR , E.CASE_MNG_NO , E.CASE_MNG_ODRNO FROM SEB120 A /*서비스사업대상자*/ LEFT JOIN SDA420 B /*서비스실행사업*/ ON A.SRVC_EXCN_BIZ_NO = B.SRVC_EXCN_BIZ_NO LEFT JOIN SDA400 S /*서비스사업*/ ON B.SRVC_BIZ_NO = S.SRVC_BIZ_NO LEFT JOIN SAA000 D /*통합기관*/ ON D.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} LEFT JOIN SEB100 E /*사례기본*/ ON A.CASE_MNG_NO = E.CASE_MNG_NO AND A.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO LEFT JOIN SEA200 F /*대상자정보*/ ON E.TRPR_INFO_NO = F.TRPR_INFO_NO LEFT JOIN AFA241 G /*영역별담당자*/ ON B.SRVC_EXCN_BIZ_NO = G.SRVC_EXCN_BIZ_NO AND E.ALTMNT_GROUP_SCLAS_SE_CD = G.ALTMNT_GROUP_SCLAS_SE_CD LEFT JOIN SCA100 H /*종사자*/ ON G.PIC_NO = H.ENFSN_NO LEFT JOIN AFA100 W /*신청접수*/ ON F.TRPR_INFO_NO = W.TRPR_INFO_NO LEFT JOIN SCA300 T /*개인정보*/ ON T.INDV_IDNTFC_NO = F.INDV_IDNTFC_NO LEFT JOIN ( SELECT TRPR_INFO_NO , ACBG FROM ( SELECT Q1.* , ROW_NUMBER() OVER(PARTITION BY Q1.TRPR_INFO_NO ORDER BY Q2.SRTNG_SQNCE DESC, Q3.SRTNG_SQNCE DESC) ROW_NO , NVL(Q2.CMMNS_CD_VALUE_NM, ' ') || NVL(Q4.CMMNS_CD_VALUE_NM, ' ') || NVL(Q3.CMMNS_CD_VALUE_NM, ' ') AS ACBG --대상자학력 FROM SEA230 Q1 LEFT JOIN SAC100 Q2 /* 최종학력구분코드 */ ON Q2.CMMNS_CD_ID = 'ACBG_SE_CD' AND Q2.CMMNS_CD_VALUE = Q1.ACBG_SE_CD LEFT JOIN SAC100 Q3 /* 졸업상태 구분코드 */ ON Q3.CMMNS_CD_ID = 'GRDTN_STTS_SE_CD' AND Q3.CMMNS_CD_VALUE = Q1.GRDTN_STTS_SE_CD LEFT JOIN SAC100 Q4 /* 학년 구분코드 */ ON Q4.CMMNS_CD_ID = 'GRADE_SE_CD' AND Q4.CMMNS_CD_VALUE = Q1.GRADE_SE_CD WHERE Q1.DEL_YN = 'N' ) WHERE ROW_NO = 1 ) C ON C.TRPR_INFO_NO = F.TRPR_INFO_NO
UNION ALL
/*멘토*/
SELECT D.INST_NO --기관번호 , D.INST_NM --기관명 , B.SRVC_EXCN_BIZ_NM --서비스실행사업명 , B.SRVC_EXCN_BIZ_NO --서비스실행사업번호 , E.ALTMNT_GROUP_SCLAS_SE_CD --배정그룹소분류구분코드 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'ALTMNT_GROUP_SCLAS_SE_CD' AND CMMNS_CD_VALUE = E.ALTMNT_GROUP_SCLAS_SE_CD ) AS DORMIT_NM --배정그룹명 , CASE WHEN F.TRPR_REL_SE_CD = '15' THEN '15' ELSE '15' END AS TRPR_REL_CD , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'TRPR_REL_SE_CD' AND CMMNS_CD_VALUE = '15' ) AS TRPR_REL --대상자관계명 , H.FLNM_ENCPT AS RSPDNT --응답자 , H.MBL_TELNO_ENCPT AS RSPDNT_RCPTN --응답자수신번호 , H.BRTH_YMD AS RSPDNT_BRDT --응답자생년월일 , F.TRPR_INFO_NO --대상자정보번호 , W.APLY_RCPT_SN --신청접수일련번호 , NVL(T.FLNM_ENCPT, F.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT --대상자 , NVL(T.BRTH_YMD, F.TRPR_BRTH_YMD) AS TRPR_BRTH_YMD --대상자생년월일(만나이) , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' AND CMMNS_CD_VALUE = NVL(T.SXDC_SE_CD, F.SXDC_SE_CD) ) AS SXDC_SE_CD_NM --대상자성별 , (SELECT CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' AND CMMNS_CD_VALUE = NVL(T.SXDC_SE_CD, F.SXDC_SE_CD) ) AS SXDC_SE_CD --대상자성별코드 , C.ACBG AS ACBG_SE_CD --대상자학력 , S.BIZ_YR , E.CASE_MNG_NO , E.CASE_MNG_ODRNO FROM SEB120 A /*서비스사업대상자*/ LEFT JOIN SDA420 B /*서비스실행사업*/ ON A.SRVC_EXCN_BIZ_NO = B.SRVC_EXCN_BIZ_NO LEFT JOIN SDA400 S /*서비스사업*/ ON B.SRVC_BIZ_NO = S.SRVC_BIZ_NO LEFT JOIN SAA000 D /*통합기관*/ ON D.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} LEFT JOIN SEB100 E /*사례기본*/ ON A.CASE_MNG_NO = E.CASE_MNG_NO AND A.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO LEFT JOIN SEA200 F /*대상자정보*/ ON E.TRPR_INFO_NO = F.TRPR_INFO_NO LEFT JOIN AFA250 G /*멘토멘티매칭*/ ON B.SRVC_EXCN_BIZ_NO = G.SRVC_EXCN_BIZ_NO AND E.ALTMNT_GROUP_SCLAS_SE_CD = G.ALTMNT_GROUP_SCLAS_SE_CD AND E.CASE_MNG_NO = G.CASE_MNG_NO AND E.CASE_MNG_ODRNO = G.CASE_MNG_ODRNO LEFT JOIN SCA100 H /*종사자*/ ON G.MENTOR_NO = H.ENFSN_NO LEFT JOIN AFA100 W /*신청접수*/ ON F.TRPR_INFO_NO = W.TRPR_INFO_NO LEFT JOIN SCA300 T /*개인정보*/ ON T.INDV_IDNTFC_NO = F.INDV_IDNTFC_NO LEFT JOIN ( SELECT TRPR_INFO_NO , ACBG FROM ( SELECT Q1.* , ROW_NUMBER() OVER(PARTITION BY Q1.TRPR_INFO_NO ORDER BY Q2.SRTNG_SQNCE DESC, Q3.SRTNG_SQNCE DESC) ROW_NO , NVL(Q2.CMMNS_CD_VALUE_NM, ' ') || NVL(Q4.CMMNS_CD_VALUE_NM, ' ') || NVL(Q3.CMMNS_CD_VALUE_NM, ' ') AS ACBG --대상자학력 FROM SEA230 Q1 LEFT JOIN SAC100 Q2 /* 최종학력구분코드 */ ON Q2.CMMNS_CD_ID = 'ACBG_SE_CD' AND Q2.CMMNS_CD_VALUE = Q1.ACBG_SE_CD LEFT JOIN SAC100 Q3 /* 졸업상태 구분코드 */ ON Q3.CMMNS_CD_ID = 'GRDTN_STTS_SE_CD' AND Q3.CMMNS_CD_VALUE = Q1.GRDTN_STTS_SE_CD LEFT JOIN SAC100 Q4 /* 학년 구분코드 */ ON Q4.CMMNS_CD_ID = 'GRADE_SE_CD' AND Q4.CMMNS_CD_VALUE = Q1.GRADE_SE_CD WHERE Q1.DEL_YN = 'N' ) WHERE ROW_NO = 1 ) C ON C.TRPR_INFO_NO = F.TRPR_INFO_NO ) X WHERE 1=1 AND X.BIZ_YR LIKE #{BIZ_YR} || '%' AND X.INST_NO LIKE #{INST_NO} || '%' AND X.SRVC_EXCN_BIZ_NO LIKE #{SRVC_EXCN_BIZ_NO} || '%' AND X.ALTMNT_GROUP_SCLAS_SE_CD LIKE #{ALTMNT_GROUP_SCLAS_SE_CD} || '%' AND X.RSPDNT LIKE ENC_B64(#{RSPDNT}) || '%' AND X.TRPR_NM_ENCPT LIKE ENC_B64(#{TRPR_NM_ENCPT}) || '%' AND X.RSPDNT_RCPTN LIKE ENC_B64(#{RSPDNT_RCPTN}) || '%' AND X.TRPR_REL_CD = #{TRPR_REL_CD}
ORDER BY X.TRPR_INFO_NO, X.TRPR_NM_ENCPT

SELECT T.* , T1.CMMNS_CD_VALUE_NM AS SXDC , T2.CMMNS_CD_VALUE_NM AS ACBG , DEC_B64(T.TRPR_NM_ENCPT) || '(' || T3.CMMNS_CD_VALUE_NM || ')' AS TRPR_NM , CASE T4.CMMNS_CD_VALUE WHEN '01' THEN '중앙' WHEN '02' THEN '대구' WHEN '03' THEN '드림' WHEN '04' THEN '대구' END AS INST_SE FROM (SELECT T1.CMMNS_CD_VALUE_NM AS SE , NVL(T3.FLNM_ENCPT, T2.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT , T.SRVY_ERA_SE_CD , NVL(T3.SXDC_SE_CD, T2.SXDC_SE_CD) AS SXDC_SE_CD , T5.ACBG_SE_CD , T.INST_NO , T.TRPR_INFO_NO
, T.QUSTNB_MNG_NO , ROW_NUMBER() OVER(PARTITION BY T.TRPR_INFO_NO, T.QUSTNB_TMPT_MNG_NO, T.SRVY_ERA_SE_CD, T.TRPR_REL_SE_CD ORDER BY T.REG_YMD DESC, T.MNG_SN DESC) AS RN , T.REG_YMD , T.MNG_SN FROM SBB600 T LEFT JOIN SAC100 T1 ON T1.CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' AND (T1.ADDTNG_MNG_VALUE1 = T.QUSTNB_TMPT_MNG_NO OR T1.ADDTNG_MNG_VALUE2 = T.QUSTNB_TMPT_MNG_NO) INNER JOIN SEA200 T2 ON T2.TRPR_INFO_NO = T.TRPR_INFO_NO LEFT JOIN SCA300 T3 ON T3.INDV_IDNTFC_NO = T2.INDV_IDNTFC_NO LEFT JOIN SDA420 T4 ON T4.SRVC_EXCN_BIZ_NO = T.SRVC_EXCN_BIZ_NO LEFT JOIN (SELECT A.* , ROW_NUMBER() OVER (PARTITION BY A.TRPR_INFO_NO ORDER BY B.ADDTNG_MNG_VALUE1 DESC, A.MNG_SN DESC) AS RN FROM SEA230 A LEFT JOIN SAC100 B ON B.CMMNS_CD_ID = 'ACBG_SE_CD' AND B.CMMNS_CD_VALUE = A.ACBG_SE_CD ) T5 ON T5.TRPR_INFO_NO = T2.TRPR_INFO_NO AND T5.RN = 1 LEFT JOIN SDA400 T01 ON T01.SRVC_BIZ_NO = T4.SRVC_BIZ_NO LEFT JOIN SBB000 T02 ON T02.QUSTNB_TMPT_MNG_NO = T.QUSTNB_TMPT_MNG_NO
WHERE 1=1
/* 서비스실행사업번호 - 과정 */ AND T4.SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO}
/* 설문지종류구분코드 */ AND T1.CMMNS_CD_VALUE = #{QUSTNB_KND_SE_CD}
/* 사업연도 */ AND T01.BIZ_YR = #{BIZ_YR}
/* 기관번호 - 기관 */ AND T.INST_NO = #{INST_NO}
/* 배정그룹소분류구분코드 - 생활동 */ AND T.ALTMNT_GROUP_SCLAS_SE_CD = #{ALTMNT_GROUP_SCLAS_SE_CD}
/* 설문진행상태구분코드 */ AND T02.SRVY_PRGRS_STTS_SE_CD = #{SRVY_PRGRS_STTS_SE_CD}
/* 설문시기구분코드 */ AND T.SRVY_ERA_SE_CD = #{SRVY_ERA_SE_CD}
/* 대상자관계구분코드 */ AND T.TRPR_REL_SE_CD = #{TRPR_REL_SE_CD}
/* 설문응답자명[암호화] */ AND T.SRVY_RSPDNT_NM_ENCPT = ENC_B64(#{SRVY_RSPDNT_NM})
/* 대상자명[암호화] */ AND T2.TRPR_NM_ENCPT = ENC_B64(#{TRPR_NM})
/* 설문수신방법구분코드 */ AND T.SRVY_RCPTN_MTHD_SE_CD = #{SRVY_RCPTN_MTHD_SE_CD}
/* 설문응답자수신번호[암호화] */ AND T.SRVY_RSPNS_RCPTN_MBL_TELNO_ENCPT = ENC_B64(#{SRVY_RSPNS_RCPTN_MBL_TELNO})
AND T.REG_YMD BETWEEN #{START_DATE} AND #{END_DATE} ) T LEFT JOIN SAC100 T1 ON T1.CMMNS_CD_ID = 'SXDC_SE_CD' AND T1.CMMNS_CD_VALUE = T.SXDC_SE_CD LEFT JOIN SAC100 T2 ON T2.CMMNS_CD_ID = 'ACBG_SE_CD' AND T2.CMMNS_CD_VALUE = T.ACBG_SE_CD LEFT JOIN SAC100 T3 ON T3.CMMNS_CD_ID = 'SRVY_ERA_SE_CD' AND T3.CMMNS_CD_VALUE = T.SRVY_ERA_SE_CD LEFT JOIN SAC100 T4 ON T4.CMMNS_CD_ID = 'APLY_RQST_TRGT_INST_SE_CD' AND (T4.ADDTNG_MNG_VALUE2 = T.INST_NO OR T4.ADDTNG_MNG_VALUE3 = T.INST_NO)
WHERE T.RN = 1
ORDER BY T.REG_YMD DESC, T.MNG_SN DESC, T.QUSTNB_MNG_NO


SELECT *
FROM
    (SELECT
          T.QUSTNB_MNG_NO
        , 'Q' || (T3.QESITM_SQNCE+1) AS QESITM
        , NVL(T2.QESITM_RSPNS_CN, NVL(T2.QESITM_SINGL_RSPNS_VALUE, T2.QESITM_COMPNO_RSPNS_VALUE)) AS RSPNS
        , T.TRPR_INFO_NO
        , T3.QESITM_SQNCE
        , T2.SRVY_RSPNS_MNG_NO
        , T.REG_YMD
        , T.MNG_SN
    FROM
        (SELECT A.*
            , ROW_NUMBER() OVER(PARTITION BY A.INST_NO, A.TRPR_INFO_NO, A.QUSTNB_TMPT_MNG_NO, A.SRVY_ERA_SE_CD, A.TRPR_REL_SE_CD ORDER BY A.REG_YMD DESC, A.MNG_SN DESC) AS RN
        FROM SBB600 A
        INNER JOIN SAC100 B
        ON B.CMMNS_CD_ID = 'QUSTNB_KND_SE_CD'
        AND B.ADDTNG_MNG_VALUE1 = A.QUSTNB_TMPT_MNG_NO

        WHERE B.CMMNS_CD_VALUE = #{QUSTNB_KND_SE_CD}
        )T
    LEFT JOIN
        (SELECT A.*
            , ROW_NUMBER() OVER (PARTITION BY A.QUSTNB_MNG_NO ORDER BY A.SRVY_RSPNS_MNG_NO DESC) AS RN
        FROM SBB500 A
        ) T1
    ON T1.QUSTNB_MNG_NO = T.QUSTNB_MNG_NO
    AND T1.RN = 1
    LEFT JOIN SBB220 T2
    ON T2.SRVY_RSPNS_MNG_NO = T1.SRVY_RSPNS_MNG_NO
    LEFT JOIN SBB010 T3
    ON T3.QUSTNB_TMPT_MNG_NO = T.QUSTNB_TMPT_MNG_NO
    AND T3.QESITM_MNG_NO = T2.QESITM_MNG_NO
    LEFT JOIN SDA420 T01
    ON T01.SRVC_EXCN_BIZ_NO = T.SRVC_EXCN_BIZ_NO
    LEFT JOIN SDA400 T02
    ON T02.SRVC_BIZ_NO = T01.SRVC_BIZ_NO
    LEFT JOIN SBB000 T03
    ON T03.QUSTNB_TMPT_MNG_NO = T.QUSTNB_TMPT_MNG_NO
    INNER JOIN SEA200 T04
    ON T04.TRPR_INFO_NO = T.TRPR_INFO_NO

    WHERE T.RN = 1
    AND T3.QESITM_MNG_NO IS NOT NULL


    /* 사업연도 */
    AND T02.BIZ_YR = #{BIZ_YR}


    /* 기관번호 - 기관 */
    AND T.INST_NO = #{INST_NO}


    /* 서비스실행사업번호 - 과정 */
    AND T01.SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO}


    /* 배정그룹소분류구분코드 - 생활동 */
    AND T.ALTMNT_GROUP_SCLAS_SE_CD = #{ALTMNT_GROUP_SCLAS_SE_CD}


    /* 설문진행상태구분코드 */
    AND T03.SRVY_PRGRS_STTS_SE_CD = #{SRVY_PRGRS_STTS_SE_CD}


    /* 설문시기구분코드 */
    AND T.SRVY_ERA_SE_CD = #{SRVY_ERA_SE_CD}


    /* 대상자관계구분코드 */
    AND T.TRPR_REL_SE_CD = #{TRPR_REL_SE_CD}


    /* 설문응답자명[암호화] */
    AND T.SRVY_RSPDNT_NM_ENCPT = ENC_B64(#{SRVY_RSPDNT_NM})


    /* 대상자명[암호화] */
    AND T04.TRPR_NM_ENCPT = ENC_B64(#{TRPR_NM})


   /* 설문수신방법구분코드 */
   AND T.SRVY_RCPTN_MTHD_SE_CD = #{SRVY_RCPTN_MTHD_SE_CD}


   /* 설문응답자수신번호[암호화] */
   AND T.SRVY_RSPNS_RCPTN_MBL_TELNO_ENCPT = ENC_B64(#{SRVY_RSPNS_RCPTN_MBL_TELNO})


    AND T.REG_YMD BETWEEN #{START_DATE} AND #{END_DATE}
    ) T

ORDER BY T.REG_YMD DESC, T.MNG_SN DESC, T.QUSTNB_MNG_NO, T.QESITM_SQNCE
